//! The fixture is generated by the upstream SQLite-backed Store::export
//! at 8231b96d70adafd64862e4f4b99f7d6cc0e340f1, using synthetic input.
use motionwright_service::{BundleImportRecoveryRequest, StudioService};
use motionwright_storage::Store;
use std::{fs, path::Path};

const ORIGINAL: &[u8] = include_bytes!("fixtures/legacy-authored.archive.json");
const ARCHIVE_SHA: &str = "df57656b52c9687cb929c9890b47152ecacd058075b3f423409e7b891e63814c";
const IMAGE_SHA: &str = "b79317fdf69dbbc71521d75be14c92de16494e59c992d6666aa7a6b9779bcd62";

fn studio(root: &Path) -> StudioService {
    StudioService::from_store(
        Store::open_with_managed_blob_root(root.join("studio.sqlite3"), root.join("blobs"))
            .unwrap(),
    )
}

#[test]
fn original_archive_inspects_imports_and_reopens_without_foreign_authority() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("original.archive.json");
    fs::write(&source, ORIGINAL).unwrap();
    let service = studio(temp.path());
    let existing = service.create_project("Existing local project").unwrap();

    let inspected = service
        .inspect_project_bundle_with_fingerprint(&source)
        .unwrap();
    assert_eq!(inspected.fingerprint.as_str(), ARCHIVE_SHA);
    assert_eq!(inspected.plan.project.title, "Archive migration original");
    assert_eq!(inspected.plan.blob_count, 2);
    assert!(
        inspected
            .migration_notes
            .iter()
            .any(|note| note.contains("caption ranges"))
    );
    assert!(service.project(inspected.plan.project.project_id).is_err());
    assert!(service.store().lock().read_blob(ARCHIVE_SHA, 4096).is_err());

    let imported = service
        .import_project_bundle_inspected(&source, &inspected.fingerprint)
        .unwrap();
    assert_eq!(imported.id, inspected.plan.project.project_id);
    assert_ne!(imported.id, existing.id);
    assert_ne!(
        imported.generation,
        inspected.plan.project.source_generation
    );
    assert_eq!(imported.revision, 0);
    assert_eq!(
        imported.scenes[0].duration,
        motionwright_domain::RationalTime::new(4, 1).unwrap()
    );
    let title = imported.scenes[0]
        .nodes
        .iter()
        .find(|node| node.kind == "text")
        .unwrap();
    assert_eq!(title.text.as_deref(), Some("An editable original"));
    assert_eq!(
        title.keyframes[0].at,
        motionwright_domain::RationalTime::new(3, 2).unwrap()
    );
    assert_eq!(title.keyframes[0].value, 360.0);
    assert!(
        imported
            .assets
            .iter()
            .any(|asset| asset.content_sha256.as_deref() == Some(IMAGE_SHA))
    );

    let saved = service
        .apply(
            imported.id,
            &imported.stamp(),
            "migration-local-edit",
            &motionwright_domain::Change::RenameProject {
                title: "Edited after migration".into(),
            },
        )
        .unwrap()
        .project;
    assert_eq!(saved.revision, 1);
    drop(service);
    let reopened = studio(temp.path());
    assert_eq!(reopened.project(imported.id).unwrap(), saved);
    assert_eq!(reopened.project(existing.id).unwrap(), existing);
    assert_eq!(
        reopened
            .store()
            .lock()
            .read_blob(ARCHIVE_SHA, 4096)
            .unwrap(),
        ORIGINAL
    );
    assert_eq!(
        reopened
            .store()
            .lock()
            .read_blob(IMAGE_SHA, 70)
            .unwrap()
            .len(),
        70
    );
    let original_commit = reopened
        .recover_project_bundle_import(&BundleImportRecoveryRequest {
            project_id: imported.id,
            fingerprint: inspected.fingerprint.clone(),
        })
        .unwrap()
        .unwrap();
    assert_eq!(original_commit.generation, imported.generation);
    assert!(
        reopened
            .import_project_bundle_inspected(&source, &inspected.fingerprint)
            .is_err()
    );
}

#[test]
fn changed_or_corrupt_archive_never_publishes_assets_or_replaces_existing_project() {
    let temp = tempfile::tempdir().unwrap();
    let source = temp.path().join("original.archive.json");
    fs::write(&source, ORIGINAL).unwrap();
    let service = studio(temp.path());
    let existing = service.create_project("Existing local project").unwrap();
    let inspected = service
        .inspect_project_bundle_with_fingerprint(&source)
        .unwrap();
    let changed = String::from_utf8(ORIGINAL.to_vec())
        .unwrap()
        .replace("editable original", "different original");
    fs::write(&source, changed).unwrap();
    assert!(
        service
            .import_project_bundle_inspected(&source, &inspected.fingerprint)
            .is_err()
    );
    let corrupt = String::from_utf8(ORIGINAL.to_vec())
        .unwrap()
        .replace(IMAGE_SHA, &"a".repeat(64));
    fs::write(&source, corrupt).unwrap();
    assert!(
        service
            .inspect_project_bundle_with_fingerprint(&source)
            .is_err()
    );
    assert!(service.project(inspected.plan.project.project_id).is_err());
    assert!(service.store().lock().read_blob(IMAGE_SHA, 70).is_err());
    assert_eq!(service.project(existing.id).unwrap(), existing);
}
